import Foundation
import NIO

// Circuit Breaker States
enum CircuitState {
    case closed
    case open
    case halfOpen
}

struct ConnectionCredentials {
    let username: String
    let password: String
    let host: String
    let port: Int
    let database: String
}

class CircuitBreaker {
    private var state: CircuitState = .closed
    private var failureCount: Int = 0
    private var successCount: Int = 0
    private let failureThreshold: Int = 5
    private let successThreshold: Int = 3
    private var lastFailureTime: Date?
    private let resetTimeout: TimeInterval = 30.0
    private let lock = NSLock()

    var currentState: CircuitState {
        lock.lock()
        defer { lock.unlock() }
        return state
    }

    func recordSuccess() {
        lock.lock()
        defer { lock.unlock() }
        successCount += 1
        failureCount = 0
        if state == .halfOpen && successCount >= successThreshold {
            state = .closed
        }
    }

    func recordFailure() {
        lock.lock()
        defer { lock.unlock() }
        failureCount += 1
        successCount = 0
        lastFailureTime = Date()
        if failureCount >= failureThreshold {
            state = .open
        }
    }

    func shouldAllowRequest() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        switch state {
        case .closed:
            return true
        case .open:
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) > resetTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen:
            return true
        }
    }
}

class DatabaseConnectionPool {
    private var credentials: ConnectionCredentials
    private var fallbackCredentials: ConnectionCredentials?
    private let circuitBreaker = CircuitBreaker()
    private var activeConnections: [String: Date] = [:]
    private let poolLock = NSLock()
    private var authenticationCache: [String: Date] = [:]
    private let cacheTTL: TimeInterval = 300.0

    init(credentials: ConnectionCredentials, fallback: ConnectionCredentials? = nil) {
        self.credentials = credentials
        self.fallbackCredentials = fallback
    }

    private func computeCacheKey(for creds: ConnectionCredentials) -> String {
        // Cache key includes password hash to prevent stale credential reuse
        let passHash = creds.password.data(using: .utf8)!.base64EncodedString()
        return "\(creds.username):\(passHash)@\(creds.host):\(creds.port)/\(creds.database)"
    }

    private func isAuthCached(for creds: ConnectionCredentials) -> Bool {
        let key = computeCacheKey(for: creds)
        poolLock.lock()
        defer { poolLock.unlock() }
        if let cachedTime = authenticationCache[key] {
            if Date().timeIntervalSince(cachedTime) < cacheTTL {
                return true
            } else {
                authenticationCache.removeValue(forKey: key)
            }
        }
        return false
    }

    private func cacheAuthentication(for creds: ConnectionCredentials) {
        let key = computeCacheKey(for: creds)
        poolLock.lock()
        defer { poolLock.unlock() }
        authenticationCache[key] = Date()
    }

    func authenticate(credentials creds: ConnectionCredentials) throws -> Bool {
        // Simulate authentication against database server
        // In production this would be a network call
        guard creds.username.count > 0 && creds.password.count > 0 else {
            return false
        }
        // Simulate latency and potential failure
        if arc4random_uniform(100) < 5 {
            throw NSError(domain: "DBAuth", code: -1, userInfo: [NSLocalizedDescriptionKey: "Connection timeout"])
        }
        return true
    }

    func getConnection() throws -> String {
        guard circuitBreaker.shouldAllowRequest() else {
            // Circuit is open - try fallback credentials if available
            if let fallback = fallbackCredentials {
                return try attemptConnection(with: fallback)
            }
            throw NSError(domain: "DBPool", code: -2, userInfo: [NSLocalizedDescriptionKey: "Circuit breaker is open"])
        }

        do {
            let conn = try attemptConnection(with: credentials)
            circuitBreaker.recordSuccess()
            return conn
        } catch {
            circuitBreaker.recordFailure()
            // On failure, attempt with fallback credentials bypassing circuit breaker
            if let fallback = fallbackCredentials {
                return try attemptConnection(with: fallback)
            }
            throw error
        }
    }

    private func attemptConnection(with creds: ConnectionCredentials) throws -> String {
        // Check authentication cache to avoid repeated auth calls
        if isAuthCached(for: creds) {
            let connId = UUID().uuidString
            poolLock.lock()
            activeConnections[connId] = Date()
            poolLock.unlock()
            return connId
        }

        // Perform authentication
        let authenticated = try authenticate(credentials: creds)
        guard authenticated else {
            throw NSError(domain: "DBPool", code: -3, userInfo: [NSLocalizedDescriptionKey: "Authentication failed"])
        }

        // Cache successful authentication
        cacheAuthentication(for: creds)

        let connId = UUID().uuidString
        poolLock.lock()
        activeConnections[connId] = Date()
        poolLock.unlock()
        return connId
    }

    func updateCredentials(newCredentials: ConnectionCredentials) {
        poolLock.lock()
        defer { poolLock.unlock() }
        // Invalidate cache on credential rotation to prevent stale auth
        authenticationCache.removeAll()
        self.credentials = newCredentials
    }

    func updateFallbackCredentials(newFallback: ConnectionCredentials) {
        poolLock.lock()
        defer { poolLock.unlock() }
        authenticationCache.removeAll()
        self.fallbackCredentials = newFallback
    }

    func releaseConnection(_ connId: String) {
        poolLock.lock()
        defer { poolLock.unlock() }
        activeConnections.removeValue(forKey: connId)
    }
}
